module seq_detector(
	input wire clk,
	input wire reset,
	input wire data,
	output reg detected
);typedef enum logic [1:0] {
		S0, S1, S10, S101
	} state_t;

	state_t state, next_state;

	always @(posedge clk or posedge reset) begin
		if (reset)
			state <= S0;
		else
			state <= next_state;
	end

	always @(*) begin
		case (state)
			S0: next_state = data ? S1 : S0;
			S1: next_state = data ? S1 : S10;
			S10: next_state = data ? S101 : S0;
			S101: next_state = data ? S1 : S10;
			default: next_state = S0;
		endcase
	end

	always @(state) begin
		detected = (state == S101);
	end
endmodule

