module binary_up_counter_8bit(
	input clk,
	input rst,
	input en,
	output reg [7:0] count_out
);

	always @(posedge clk) begin
		if (rst)
			count_out <= 8'b0; // Reset to zero
		else if (en)
			count_out <= count_out + 1;
	end

