module top_module (
  input in1,
  input in2,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter M=0, N=1, O=2;

    always_comb begin
		case (state)
			M: next_state = (in1 || in2) ? O : N;
			N: next_state = (in1 || in2) ? M : O;
			O: next_state = (in1 || in2) ? N : M;
		endcase
    end

	assign out = (state==M) || (state==O);

endmodule

