module fasm_spsram_wbr (
   dat_o,
   dat_i, adr_i, wre_i, stb_i, rst_i, clk_i
   );
   parameter AW = 8;  
   parameter DW = 32; 
   output [DW-1:0] dat_o; 
   input [DW-1:0]  dat_i; 
   input [AW-1:0]  adr_i; 
   input 	   wre_i; 
   input 	   stb_i; 
   input 	   rst_i,
		   clk_i;
