module Divide(
    input           clock,
    input           reset,
    input           OP_div,     
    input           OP_divu,    
    input  [31:0]   Dividend,
    input  [31:0]   Divisor,
    output [31:0]   Quotient,
    output [31:0]   Remainder,
    output          Stall       
    );
    reg             active;     
    reg             neg;        
    reg [4:0]       cycle;      
    reg [31:0]      result;     
    reg [31:0]      denom;      
    reg [31:0]      work;       
    wire [32:0]     sub = { work[30:0], result[31] } - denom;
    assign Quotient = !neg ? result : -result;
    assign Remainder = work;
    assign Stall = active;
    always @(posedge clock) begin
        if (reset) begin
            active <= 0;
            neg <= 0;
            cycle <= 0;
            result <= 0;
            denom <= 0;
            work <= 0;
        end
        else begin
            if (OP_div) begin
                cycle <= 5'd31;
                result <= (Dividend[31] == 0) ? Dividend : -Dividend;
                denom <= (Divisor[31] == 0) ? Divisor : -Divisor;
                work <= 32'b0;
                neg <= Dividend[31] ^ Divisor[31];
                active <= 1;
            end
            else if (OP_divu) begin
                cycle <= 5'd31;
                result <= Dividend;
                denom <= Divisor;
                work <= 32'b0;
                neg <= 0;
                active <= 1;
            end
            else if (active) begin
                if (sub[32] == 0) begin
                    work <= sub[31:0];
                    result <= {result[30:0], 1'b1};
                end
                else begin
                    work <= {work[30:0], result[31]};
                    result <= {result[30:0], 1'b0};
                end
                if (cycle == 0) begin
                    active <= 0;
                end
                cycle <= cycle - 5'd1;
            end
        end
    end
endmodule

