reg signed [17:0] b_reg;
reg signed [33:0] prod;
always @ (posedge clk) begin
    a_reg <= a;
    b_reg <= b;
end
always @ (posedge clk) begin
    prod <= a_reg * b_reg;
end
assign p = prod;
endmodule
